import {safeAvatar} from './trade-model.mjs';
import {supabase,currentUser,login} from './auth-client.mjs';
import {profileContactValues} from './account-model.mjs';
const $=id=>document.getElementById(id);let user=null,revision=0,loading=false;
function paintSharing(id,revealed){const b=$(id);b.textContent=revealed?'Revealed':'Hidden';b.setAttribute('aria-pressed',String(revealed));b.setAttribute('aria-label',(id==='share-game-id'?'In-Game ID':'Discord Username')+' sharing: '+(revealed?'Revealed':'Hidden'));}
for(const id of ['share-discord'])$(id).onclick=()=>{paintSharing(id,$(id).getAttribute('aria-pressed')!=='true');$('profile-status').textContent='Unsaved changes';};
async function refresh(){const id=++revision;try{user=await currentUser();if(id!==revision)return;$('signed-out').hidden=!!user;$('signed-in').hidden=!user;if(!user)return;$('profile-name').value=user.user_metadata?.full_name||user.user_metadata?.name||'Player';$('game-id').value='';$('discord-username').value='';$('trade-listing-enabled').checked=false;$('public-album-enabled').checked=false;paintSharing('share-discord',false);$('account-status').textContent='Loading your settings…';loading=true;$('save-profile').disabled=true;const profile=await supabase.from('profiles').select('*').eq('user_id',user.id).maybeSingle();if(profile.error)throw profile.error;if(id!==revision)return;if(profile.data){$('profile-name').value=profile.data.display_name;$('game-id').value=profile.data.game_id;$('discord-username').value=profile.data.discord_username??'';$('trade-listing-enabled').checked=profile.data.trade_enabled===true;$('public-album-enabled').checked=profile.data.album_public===true;paintSharing('share-discord',profile.data.share_discord===true);}$('account-status').textContent='';$('save-profile').disabled=false;}catch(error){$('account-status').textContent='Account settings are unavailable. '+error.message;}finally{loading=false;}}
for(const provider of ['discord'])$(provider+'-login').onclick=async()=>{try{$('login-status').textContent='Opening '+provider+'…';await login(provider);}catch(error){$('login-status').textContent=error.message;}};
$('logout').onclick=async()=>{const {error}=await supabase.auth.signOut({scope:'local'});if(error){$('account-status').textContent=error.message;return;}await refresh();};
$('profile-form').onsubmit=async e=>{e.preventDefault();if(!user||loading)return;const displayName=$('profile-name').value.trim();if(!displayName){$('profile-status').textContent='Enter a display name.';return;}$('save-profile').disabled=true;try{const {error}=await supabase.from('profiles').upsert({user_id:user.id,trade_enabled:$('trade-listing-enabled').checked,album_public:$('public-album-enabled').checked,avatar_url:safeAvatar(user.user_metadata?.avatar_url),...profileContactValues({displayName,gameId:$('game-id').value,discordUsername:$('discord-username').value,shareGameId:true,shareDiscord:$('share-discord').getAttribute('aria-pressed')==='true'})},{onConflict:'user_id'});if(error)throw error;$('profile-status').textContent='Profile saved.';}catch(error){$('profile-status').textContent=['PGRST204','42703'].includes(error.code)?'Profile settings need the latest database update before they can be saved.':error.message;}finally{$('save-profile').disabled=false;}};
supabase.auth.onAuthStateChange(()=>setTimeout(refresh,0));
await refresh();

window.addEventListener('game-uid-saved',refresh);
